// Types for the generated bundle (build-claude-mod.sh): the handles the mod uses, loosely typed.
export type Game = {
  readonly S: any;
  readonly MODE: 'life' | 'chaos' | 'visit';
  readonly VISIT: any;
  readonly camX: number;
  chaosCam: number;
  chaosTool: string;
  nick: string;
  readonly weather: string;
  readonly holiday: string | null;
  readonly people: any[];
  readonly me: any;
  T: number;
  W: number;
  H: number;
  VIEW_W: number;
  ERAS: { name: string }[];
  CHAOS_TOOLS: [string, string, string][];
  TRAITS: [string, string][];
  LANDMARKS: any[];
  SEASONS: string[];
  levelOf: (xp: number) => number;
  fmt: (n: number) => string;
  population: () => number;
  isNight: () => boolean;
  paintUi: () => void;
  wake: () => void;
  moveCam: (to: number) => void;
  pickGender: (g: 'f' | 'm') => void;
  useTool: (x: number, y: number) => void;
  enterChaos: (era: number) => void;
  leaveChaos: () => void;
  placeSign: () => void;
  myCode: () => Promise<string>;
  openCode: (text: string) => Promise<unknown>;
  leaveVisit: () => void;
  visitNote: () => Promise<void>;
  openVisitCard: () => Promise<void>;
  $: (id: string) => any;
};
export const HIDDEN_IDS: readonly string[];
export function makeGame(env: Record<string, unknown>): Game;
